/** WebP + PNG fallback for service/home card images (mobile data savings) */
function serviceImgWebp(src) {
  return src && /\.png$/i.test(src) ? src.replace(/\.png$/i, '.webp') : null;
}

/** iOS-safe: single img with webp→png onError (picture/source can blank on Safari grids) */
function ServiceImg({ src, alt = '', loading = 'eager', style, ...rest }) {
  const webp = serviceImgWebp(src);
  const [imgSrc, setImgSrc] = useState(() => webp || src);
  const imgStyle = { display: 'block', maxWidth: '100%', ...style };

  useEffect(() => {
    setImgSrc(webp || src);
  }, [src, webp]);

  const onError = useCallback(() => {
    if (webp && imgSrc !== src) setImgSrc(src);
  }, [webp, src, imgSrc]);

  return (
    <img
      src={imgSrc}
      alt={alt}
      loading={loading}
      decoding="async"
      style={imgStyle}
      onError={onError}
      {...rest}
    />
  );
}

/** iOS-safe 2-column grid + odd last tile centered at half width */
const MOBILE_GRID_2 = { display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: 10, width: '100%', alignItems: 'stretch' };

function SvcGrid2({ items, renderItem, gap = 10 }) {
  const oddLast = items.length % 2 === 1;
  const halfW = `calc(50% - ${gap / 2}px)`;
  return (
    <div style={{ ...MOBILE_GRID_2, gap }}>
      {items.map((item, i) => (
        <div
          key={item.id || i}
          style={{
            minWidth: 0,
            display: 'flex',
            flexDirection: 'column',
            ...(oddLast && i === items.length - 1 ? { gridColumn: '1 / -1', maxWidth: halfW, marginLeft: 'auto', marginRight: 'auto', width: '100%' } : null),
          }}
        >
          {renderItem(item, i)}
        </div>
      ))}
    </div>
  );
}
