/** All bookable services for vendor onboarding selection */
function allVendorSelectableServices() {
  const list = [];
  for (const [catId, cfg] of Object.entries(SUB_CATEGORIES)) {
    for (const s of cfg.svcs) {
      list.push({ service_id: s.id, category_id: catId, name: s.name, cat: cfg.title });
    }
  }
  for (const s of SVCS) {
    if (!SUB_CATEGORIES[s.id]) {
      list.push({ service_id: s.id, category_id: s.id, name: s.name, cat: s.cat });
    }
  }
  return list;
}

function vendorServiceNameMap(allSvcs) {
  return Object.fromEntries(allSvcs.map(s => [s.service_id, s]));
}

function VendorServicePicker({ allSvcs, selected, onToggle, searchPlaceholder = 'Search services…', maxHeight = 420 }) {
  const [q, setQ] = useState('');
  const filtered = useMemo(() => {
    const term = q.trim().toLowerCase();
    if (!term) return allSvcs;
    return allSvcs.filter(s =>
      s.name.toLowerCase().includes(term) || s.cat.toLowerCase().includes(term),
    );
  }, [allSvcs, q]);

  const serving = filtered.filter(s => selected[s.service_id]);
  const availableByCat = useMemo(() => {
    const acc = {};
    for (const s of filtered) {
      if (selected[s.service_id]) continue;
      if (!acc[s.cat]) acc[s.cat] = [];
      acc[s.cat].push(s);
    }
    return acc;
  }, [filtered, selected]);

  const selectedCount = allSvcs.filter(s => selected[s.service_id]).length;

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10, gap: 8, flexWrap: 'wrap' }}>
        <div style={{ fontSize: 12, fontWeight: 700, color: C.grn }}>
          Your services ({selectedCount})
        </div>
        <div style={{ fontSize: 11, color: C.dim }}>{allSvcs.length} total in catalog</div>
      </div>
      {selectedCount > 0 ? (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 14, padding: 10, background: `${C.grn}12`, border: `1px solid ${C.grn}44`, borderRadius: 10 }}>
          {allSvcs.filter(s => selected[s.service_id]).map(s => (
            <button key={s.service_id} type="button" onClick={() => onToggle(s.service_id)}
              style={{ display: 'inline-flex', alignItems: 'center', gap: 4, padding: '4px 10px', borderRadius: 16, border: `1px solid ${C.grn}`, background: C.surf, color: C.txt, fontSize: 11, fontWeight: 600, cursor: 'pointer', fontFamily: FF }}>
              {s.name} <span style={{ color: C.red, fontWeight: 800 }}>×</span>
            </button>
          ))}
        </div>
      ) : (
        <div style={{ fontSize: 12, color: C.dim, marginBottom: 14, padding: 10, background: C.deep, borderRadius: 8 }}>
          No services selected yet — pick from the categories below.
        </div>
      )}

      <input value={q} onChange={e => setQ(e.target.value)} placeholder={searchPlaceholder}
        style={{ ...S.inp(), marginBottom: 12, fontSize: 13 }} />

      <div style={{ fontSize: 12, fontWeight: 700, color: C.acc, marginBottom: 8 }}>
        Available to add ({filtered.length - serving.length})
      </div>
      <div style={{ maxHeight, overflowY: 'auto', border: BDR, borderRadius: 10, padding: '4px 10px' }}>
        {Object.entries(availableByCat).map(([cat, svcs]) => (
          <div key={cat} style={{ marginBottom: 10, paddingTop: 8 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: C.acc }}>{cat} ({svcs.length})</div>
              <button type="button" onClick={() => svcs.forEach(s => { if (!selected[s.service_id]) onToggle(s.service_id); })}
                style={{ background: 'none', border: 'none', color: C.cyan, fontSize: 10, fontWeight: 700, cursor: 'pointer', fontFamily: FF }}>
                Add all
              </button>
            </div>
            {svcs.map(s => (
              <label key={s.service_id} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '7px 0', borderBottom: `1px solid ${C.bdr}`, cursor: 'pointer', fontSize: 13 }}>
                <input type="checkbox" checked={false} onChange={() => onToggle(s.service_id)} />
                <span style={{ color: C.txt }}>{s.name}</span>
              </label>
            ))}
          </div>
        ))}
        {!Object.keys(availableByCat).length && (
          <div style={{ textAlign: 'center', color: C.dim, fontSize: 12, padding: 20 }}>
            {q ? 'No matching services' : 'All services selected ✓'}
          </div>
        )}
      </div>
    </div>
  );
}

async function vendorOnboardFetch(action, payload = {}, pin) {
  const headers = { apikey: SB_KEY, Authorization: `Bearer ${SB_KEY}`, 'Content-Type': 'application/json' };
  if (pin) headers['x-vendor-admin-pin'] = pin;
  const res = await fetch(VENDOR_FN, {
    method: 'POST',
    headers,
    body: JSON.stringify({ action, ...payload }),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || 'Request failed');
  return data;
}

function serviceCategoryId(serviceId) {
  if (!serviceId) return '';
  for (const [catId, cfg] of Object.entries(SUB_CATEGORIES)) {
    if (cfg.svcs?.some((s) => s.id === serviceId)) return catId;
  }
  return serviceId;
}

async function forwardGeocode(address) {
  if (!address?.trim()) return null;
  try {
    const r = await fetch(
      `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(address.trim())}&format=json&limit=1&countrycodes=in`,
      { headers: { Accept: 'application/json', 'Accept-Language': 'en', 'User-Agent': 'ScanV/5.5' } },
    );
    const data = await r.json();
    if (data?.[0]?.lat && data?.[0]?.lon) {
      return { lat: parseFloat(data[0].lat), lng: parseFloat(data[0].lon) };
    }
  } catch (_) { /* ignore */ }
  return null;
}

async function resolveDispatchCoords({ lat, lng, location }) {
  if (lat != null && lng != null) return { lat, lng };
  const geo = await forwardGeocode(location);
  return geo || { lat: null, lng: null };
}

async function invokeBookingDispatch(opts, addToast) {
  if (isCloudSubCardService({ id: opts.serviceId, parent: opts.categoryId })) {
    return { success: true, dispatch_skipped: true, reason: 'cloud_digital_service' };
  }
  try {
    const coords = await resolveDispatchCoords(opts);
    const r = await sb().functions.invoke('booking-dispatch', {
      body: {
        action: 'start',
        booking_id: opts.bookingId,
        service_id: opts.serviceId || '',
        category_id: opts.categoryId || '',
        customer_id: opts.customerId || null,
        service_name: opts.serviceName,
        lat: coords.lat,
        lng: coords.lng,
        location: opts.location || '',
        date: opts.date || null,
        time: opts.time || null,
      },
    });
    if (r.error) {
      addToast?.(r.error.message || 'Partner alerts failed', 'error');
      return { error: r.error.message };
    }
    if (r.data?.error) {
      addToast?.(r.data.error, 'error');
      return r.data;
    }
    const n = r.data?.nearest_count ?? r.data?.vendors_notified?.length ?? 0;
    if (r.data?.dispatch_skipped) {
      addToast?.('Partner dispatch is turned off in admin settings', 'error');
    } else if (n > 0) {
      addToast?.(`Offering job to nearest partner in the ScanV app — SMS/call/WhatsApp sent as backup`, 'success');
    } else if (r.data?.empty_queue) {
      const eq = r.data.empty_queue;
      const hint = eq.reason === 'vendors_missing_gps'
        ? 'Partners need GPS on file — ask them to open Vendor portal'
        : eq.reason === 'all_candidates_busy_or_blocked'
          ? 'Nearest partners are busy on other jobs'
          : 'No partners matched — check service & location';
      addToast?.(`No partners alerted (${eq.reason}). ${hint}`, 'error');
    } else if (r.data?.success) {
      addToast?.('Searching for partners — alerts will retry shortly', 'success');
    }
    return r.data;
  } catch (e) {
    addToast?.(e.message || 'Partner alerts failed', 'error');
    return { error: e.message };
  }
}

async function invokeCloudBookingComplete(opts, addToast) {
  try {
    const r = await sb().functions.invoke('booking-dispatch', {
      body: {
        action: 'cloud_complete',
        booking_id: opts.bookingId,
        customer_id: opts.customerId || null,
      },
    });
    if (r.error) {
      addToast?.(r.error.message || 'Confirmation email could not be sent', 'error');
      return { error: r.error.message };
    }
    if (r.data?.error) {
      addToast?.(r.data.error, 'error');
      return r.data;
    }
    if (r.data?.notifications?.email?.sent) {
      addToast?.('Confirmation email sent', 'success');
    } else if (r.data?.notifications?.email?.error === 'no_customer_email') {
      addToast?.('Booking saved — add your email in Profile for confirmations', 'info');
    }
    return r.data;
  } catch (e) {
    addToast?.(e.message || 'Confirmation email failed', 'error');
    return { error: e.message };
  }
}

