/** Auto-rotating hero carousel — one full-width card at a time (no peek) */
function HomeHeroCarousel({ services, onSelect, intervalMs = 4500 }) {
  const [idx, setIdx] = useState(0);
  const n = services.length;
  const pauseRef = useRef(false);
  const viewRef = useRef(null);
  const [slideW, setSlideW] = useState(0);

  useEffect(() => {
    const el = viewRef.current;
    if (!el) return undefined;
    const measure = () => setSlideW(Math.round(el.getBoundingClientRect().width));
    measure();
    const ro = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(measure) : null;
    ro?.observe(el);
    window.addEventListener('resize', measure);
    return () => {
      ro?.disconnect();
      window.removeEventListener('resize', measure);
    };
  }, []);

  useEffect(() => {
    if (n <= 1) return undefined;
    const id = setInterval(() => {
      if (!pauseRef.current) setIdx(i => (i + 1) % n);
    }, intervalMs);
    return () => clearInterval(id);
  }, [n, intervalMs]);

  if (!n) return null;

  return (
    <div
      style={{ marginBottom: 10, width: '100%', maxWidth: '100%', minWidth: 0, overflow: 'hidden' }}
      onMouseEnter={() => { pauseRef.current = true; }}
      onMouseLeave={() => { pauseRef.current = false; }}
      onTouchStart={() => { pauseRef.current = true; }}
      onTouchEnd={() => { setTimeout(() => { pauseRef.current = false; }, 2800); }}
    >
      <div
        ref={viewRef}
        style={{ overflow:'hidden', borderRadius:16, height:168, width:'100%', maxWidth:'100%', position:'relative', isolation:'isolate', clipPath:'inset(0 round 16px)' }}
      >
        <div
          style={{
            display:'flex',
            height:'100%',
            width: slideW ? slideW * n : '100%',
            transform: slideW ? `translate3d(-${idx * slideW}px,0,0)` : 'none',
            transition:'transform 0.72s cubic-bezier(0.4, 0, 0.2, 1)',
            willChange:'transform',
          }}
        >
          {services.map((svc, i) => (
            <div key={svc.id} style={{ width: slideW || '100%', minWidth: slideW || '100%', maxWidth: slideW || '100%', height:168, flexShrink:0, overflow:'hidden', boxSizing:'border-box' }}>
              <HomeModelCard svc={svc} onClick={() => onSelect(svc)} hero index={i} />
            </div>
          ))}
        </div>
      </div>
      <div style={{ display:'flex', justifyContent:'center', flexWrap:'wrap', gap:5, marginTop:8, width:'100%' }}>
        {services.map((svc, i) => (
          <button
            key={svc.id}
            type="button"
            aria-label={`Show ${svc.name}`}
            onClick={() => setIdx(i)}
            style={{
              width: i === idx ? 18 : 7,
              height: 7,
              borderRadius: 99,
              border:'none',
              padding:0,
              cursor:'pointer',
              background: i === idx ? C.acc : `${C.dim}55`,
              transition:'width 0.25s ease, background 0.25s ease',
              animation: i === idx ? 'heroPulse 2.4s ease-in-out infinite' : 'none',
            }}
          />
        ))}
      </div>
    </div>
  );
}

