function ServiceFeaturedCard(props) { return <HomeModelCard {...props} hero={props.fullWidth && props.svc?.household} />; }

function CategoryPill({ categoryId, theme, sm }) {
  const t = SUB_CATEGORIES[categoryId]?.themes?.[theme];
  if (!t) return null;
  return (
    <span style={{ background: t.bg, color: t.color, border: `1.5px solid ${t.border}`, borderRadius: 99, fontSize: sm ? 11 : 12, fontWeight: 800, padding: sm ? '2px 8px' : '3px 10px' }}>
      {t.label}
    </span>
  );
}
function HhCategoryPill({ theme, sm }) { return <CategoryPill categoryId="household" theme={theme} sm={sm} />; }
function CloudCategoryPill({ theme, sm }) { return <CategoryPill categoryId="cloud" theme={theme} sm={sm} />; }

function PriceTag({ svc, sm }) {
  const { mrp, price } = effectiveSvcPrices(svc);
  const unit = svc.unit === 'hour' ? '/hr' : svc.unit === 'month' ? '/mo' : svc.unit === 'project' ? '/project' : svc.unit === 'course' ? '/course' : '';
  const pctOff = mrp > price ? Math.round((1 - price / mrp) * 100) : 0;
  return (
    <div style={{ display: 'flex', alignItems: 'baseline', gap: 6, flexWrap: 'wrap' }}>
      {mrp > price && <span style={{ color: C.dim, fontSize: sm ? 12 : 13, textDecoration: 'line-through', fontWeight: 600 }}>₹{fmtRs(mrp)}{unit}</span>}
      <span style={{ color: C.acc, fontSize: sm ? 15 : 17, fontWeight: 800 }}>₹{fmtRs(price)}{unit}</span>
      {pctOff > 0 && <span style={{ background: '#fef3c7', color: '#b45309', fontSize: 10, fontWeight: 800, padding: '2px 6px', borderRadius: 4 }}>{pctOff}% OFF</span>}
    </div>
  );
}

function cloudCourseMatchesEnrollment(svc, feeView) {
  if (!feeView?.sgr_paid) return false;
  if (feeView.course_id && feeView.course_id === svc.id) return true;
  const enrolled = String(feeView.course_name || '').trim().toLowerCase();
  const name = String(svc.name || '').trim().toLowerCase();
  return enrolled && name && enrolled === name;
}

function cloudCourseBookReady(svc, feeView) {
  return cloudCourseMatchesEnrollment(svc, feeView) && Number(feeView?.course_fee_paise) > 0;
}

function effectiveCloudCatalogPrice(svc, feeView = null) {
  const catalog = Number(svc?.price) || 0;
  const enrolled = Number(feeView?.course_fee_paise) || 0;
  // Live catalog (Pricing Admin → service_prices_public) wins over stale enrollment snapshot.
  return catalog > 0 ? catalog : enrolled;
}

function withCloudCourseFee(svc, feeView) {
  if (!cloudCourseBookReady(svc, feeView)) return svc;
  const feePaise = effectiveCloudCatalogPrice(svc, feeView);
  if (!feePaise) return svc;
  return { ...svc, price: feePaise, mrp: Math.max(Number(svc.mrp) || feePaise, feePaise) };
}

function CloudCoursePriceTag({ svc, sm, feeView, onFillSgr }) {
  const isEnrolledCourse = cloudCourseMatchesEnrollment(svc, feeView);
  if (!isEnrolledCourse) {
    return (
      <button
        type="button"
        onClick={(e) => { e.stopPropagation(); onFillSgr?.(svc); }}
        style={{
          background: 'none',
          border: 'none',
          padding: 0,
          cursor: onFillSgr ? 'pointer' : 'default',
          color: C.gold,
          fontSize: sm ? 13 : 14,
          fontWeight: 800,
          letterSpacing: '0.02em',
          fontFamily: FF,
          textDecoration: onFillSgr ? 'underline' : 'none',
        }}
      >
        Fill SGR
      </button>
    );
  }
  const feePaise = effectiveCloudCatalogPrice(svc, feeView);
  if (!feePaise) {
    return (
      <span style={{ color: C.gold, fontSize: sm ? 11 : 12, fontWeight: 800, letterSpacing: '0.02em', fontFamily: FF }}>
        Awaiting payment
      </span>
    );
  }
  if (Number(feeView?.course_paid_paise) > 0 || feeView?.status === 'enrolled' || feeView?.status === 'completed') {
    return (
      <span style={{ color: C.grn, fontSize: sm ? 11 : 12, fontWeight: 800, letterSpacing: '0.02em', fontFamily: FF }}>
        Enrolled
      </span>
    );
  }
  const priced = { ...svc, price: feePaise, mrp: Math.max(Number(svc.mrp) || feePaise, feePaise) };
  return <PriceTag svc={priced} sm={sm} />;
}

function ServicePriceTag({ svc, sm, categoryId, cloudFeeView, onFillSgr }) {
  if (categoryId === 'cloud' && svc?.parent === 'cloud' && svc.id !== SGR_SERVICE_ID) {
    return <CloudCoursePriceTag svc={svc} sm={sm} feeView={cloudFeeView} onFillSgr={onFillSgr} />;
  }
  return <PriceTag svc={svc} sm={sm} />;
}

