function HouseholdSvcCard(props) { return <CategorySvcCard categoryId="household" {...props} />; }
function CloudSvcCard(props) { return <CategorySvcCard categoryId="cloud" {...props} />; }

function CategoryListBody({ categoryId, onSelect, onAdmit, onFillSgr, apikey, cloudFeeView: cloudFeeViewProp }) {
  const cfg = SUB_CATEGORIES[categoryId];
  const { feeView: fetchedCloudFeeView } = useStudentCloudFeeView(
    categoryId === 'cloud' && cloudFeeViewProp == null ? apikey : null,
  );
  const cloudFeeView = cloudFeeViewProp ?? fetchedCloudFeeView;
  const [filter, setFilter] = useState('all');
  if (!cfg) return null;
  const list = visibleSvcs(cfg.svcs).filter(s => filter === 'all' || s.theme === filter);
  const knownThemes = new Set(cfg.themeOrder);
  const extraThemes = [...new Set(list.map(s => s.theme).filter(t => t && !knownThemes.has(t)))];
  const renderThemes = [...cfg.themeOrder, ...extraThemes];
  const accent = SVC_CARD_THEME[categoryId]?.b2 || C.acc;
  const pills = [['all', 'All', accent, C.surf], ...cfg.themeOrder.map(k => [k, cfg.themes[k].label, cfg.themes[k].color, cfg.themes[k].bg])];
  if (!list.length) {
    return (
      <div style={{ padding: '32px 16px', textAlign: 'center' }}>
        <div style={{ fontSize: 28, marginBottom: 8 }}>🔍</div>
        <div style={{ color: C.txt, fontWeight: 700, fontSize: 16, marginBottom: 4 }}>No services available</div>
        <div style={{ color: C.dim, fontSize: 14, lineHeight: 1.5 }}>This category is being updated — check back soon.</div>
      </div>
    );
  }
  return (
    <div style={{ padding: '14px 16px 24px' }}>
      {categoryId === 'cloud' && onAdmit && (
        <button type="button" onClick={onAdmit} style={{ width: '100%', textAlign: 'left', marginBottom: 14, border: '1.5px solid #93C5FD', background: 'linear-gradient(135deg,#EFF6FF,#DBEAFE)', borderRadius: 14, padding: '14px 14px', cursor: 'pointer', fontFamily: FF }}>
          <div style={{ fontSize: 13, fontWeight: 800, color: '#1D4ED8', letterSpacing: '0.06em', textTransform: 'uppercase' }}>Skill Gap Review (SGR) - Form A1</div>
          <div style={{ fontSize: 14, color: C.sub, marginTop: 4, lineHeight: 1.45 }}>Verify mobile · book a schedule · Razorpay. A consultant calls you within 72 hours.</div>
        </button>
      )}
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 14 }}>
        {pills.map(([k, l, col, bg]) => (
          <button key={k} onClick={() => setFilter(k)} style={{ padding: '8px 14px', borderRadius: 99, border: filter === k ? `2px solid ${col}` : BDR, background: filter === k ? bg : C.surf, color: filter === k ? col : C.sub, fontSize: 13, fontWeight: 800, cursor: 'pointer', fontFamily: FF }}>
            {l}
          </button>
        ))}
      </div>
      {renderThemes.map(theme => {
        const items = sortSvcsByName(list.filter(s => s.theme === theme));
        if (!items.length) return null;
        const t = cfg.themes[theme] || { label: theme, color: accent, bg: C.surf, tagline: '' };
        return (
          <div key={theme} style={{ marginBottom: 18 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10, flexWrap: 'wrap' }}>
              <CategoryPill categoryId={categoryId} theme={theme} />
              <span style={{ color: C.dim, fontSize: 13, fontWeight: 600 }}>{t.tagline}</span>
            </div>
            <SvcGrid2
              items={items}
              renderItem={(svc) => <CategorySvcCard categoryId={categoryId} svc={svc} onClick={() => onSelect(svc)} compact cloudFeeView={cloudFeeView} onFillSgr={onFillSgr} />}
            />
          </div>
        );
      })}
      <AssistBanner />
    </div>
  );
}
function HouseholdListBody(props) { return <CategoryListBody categoryId="household" {...props} />; }
function CloudListBody(props) { return <CategoryListBody categoryId="cloud" {...props} />; }

function ServiceSearchResults({ query, categories, onCategory, onSubSvc, renderCategory, ...searchSubs }) {
  const q = query.trim();
  if (!q) return null;
  const subBlocks = Object.entries(SUB_CATEGORIES)
    .map(([id, cfg]) => ({ id, title: cfg.title, items: sortSvcsByName(searchSubs[id] || []) }))
    .filter(b => b.items.length > 0)
    .sort((a, b) => String(a.title || '').localeCompare(String(b.title || ''), 'en', { sensitivity: 'base' }));
  const total = categories.length + subBlocks.reduce((a, b) => a + b.items.length, 0);
  if (!total) {
    return (
      <div style={{ ...S.card(), padding: 24, textAlign: 'center', marginBottom: 14 }}>
        <div style={{ fontSize: 28, marginBottom: 8 }}>🔍</div>
        <div style={{ color: C.txt, fontWeight: 700, fontSize: 16, marginBottom: 4 }}>No services found</div>
        <div style={{ color: C.dim, fontSize: 14, lineHeight: 1.5 }}>Try &ldquo;kitchen clean&rdquo;, &ldquo;doctor home&rdquo;, &ldquo;legal&rdquo;, or &ldquo;tiffin&rdquo;</div>
      </div>
    );
  }
  return (
    <>
      <div style={{ marginBottom: 14 }}>
        <div style={{ color: C.txt, fontSize: 17, fontWeight: 800, marginBottom: 3 }}>Search results</div>
        <div style={{ color: C.dim, fontSize: 14, fontWeight: 500 }}>{total} found for &ldquo;{q}&rdquo;</div>
      </div>
      {subBlocks.map(({ id, title, items }) => (
        <div key={id} style={{ marginBottom: 16 }}>
          <div style={{ color: C.txt, fontSize: 15, fontWeight: 800, marginBottom: 10 }}>{title} · {items.length}</div>
          <SvcGrid2
            items={items}
            renderItem={(svc) => <CategorySvcCard categoryId={id} svc={svc} onClick={() => onSubSvc(id, svc)} compact />}
          />
        </div>
      ))}
      {categories.length > 0 && (
        <div style={{ marginBottom: 14 }}>
          {subBlocks.length > 0 && <div style={{ color: C.txt, fontSize: 15, fontWeight: 800, marginBottom: 10 }}>Categories · {categories.length}</div>}
          <SvcGrid2 gap={12} items={categories} renderItem={(s, i) => renderCategory(s, i)} />
        </div>
      )}
    </>
  );
}

function Toast({toasts}) {
  if (!toasts.length) return null;
  return (
    <div className="scanv-toast-stack" aria-live="polite">
      {toasts.map(t=>(
        <div key={t.id} className="scanv-toast-item" style={{background:t.type==='error'?`${C.red}22`:t.type==='success'?`${C.grn}22`:`${C.cyan}22`,border:`1px solid ${t.type==='error'?C.red:t.type==='success'?C.grn:C.cyan}`,color:C.txt}}>
          {t.msg}
        </div>
      ))}
    </div>
  );
}

